$$
\begin{aligned}
2 I & =\int_{-2}^{2} \frac{1+x^{2}}{1+2^{x}} d x+\int_{2}^{-2}-\frac{1+x^{2}}{1+2^{-x}} d x=\int_{-2}^{2} \frac{1+x^{2}}{1+2^{x}}+\frac{1+x^{2}}{1+2^{-x}} d x \\
& =\int_{-2}^{2} \frac{1+x^{2}}{1+2^{x}}+\frac{\left(1+x^{2}\right) 2^{x}}{1+2^{x}} d x=\int_{-2}^{2} \frac{\left(1+x^{2}\right) \cdot\left(1+2^{x}\right)}{1+2^{x}} d x=\int_{-2}^{2} 1+x^{2} d x=4+\frac{16}{3}=\frac{28}{3}
\end{aligned}
$$

